PRAGMA defer_foreign_keys=ON;
CREATE TABLE schema_version_v6(version INTEGER PRIMARY KEY CHECK(version IN(1,2,3,4,5,6)),backend TEXT NOT NULL CHECK(backend='sqlite'),checksum TEXT NOT NULL) STRICT;
INSERT INTO schema_version_v6 SELECT * FROM schema_version;
DROP TABLE schema_version;
ALTER TABLE schema_version_v6 RENAME TO schema_version;
CREATE TABLE interview(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('scheduled','in_progress','completed','cancelled')),revision INTEGER NOT NULL CHECK(revision>0),scheduled_at INTEGER NOT NULL,actual_started_at INTEGER,actual_ended_at INTEGER,backfilled INTEGER NOT NULL CHECK(backfilled IN(0,1)),author_subject_id TEXT NOT NULL,recorded_at INTEGER NOT NULL,reason_payload_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),CHECK(backfilled=0 OR status='completed'),CHECK(actual_ended_at IS NULL OR (actual_started_at IS NOT NULL AND actual_ended_at>=actual_started_at)),CHECK(status<>'scheduled' OR (actual_started_at IS NULL AND actual_ended_at IS NULL)),CHECK(status<>'in_progress' OR (actual_started_at IS NOT NULL AND actual_ended_at IS NULL)),CHECK(status<>'completed' OR (actual_started_at IS NOT NULL AND actual_ended_at IS NOT NULL)),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,author_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,id,employee_id,reason_payload_id) REFERENCES interview_payload(org_id,interview_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE interview_participant(org_id TEXT NOT NULL,interview_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 19),kind TEXT NOT NULL CHECK(kind IN('subject','employee')),subject_id TEXT,employee_id TEXT,PRIMARY KEY(org_id,interview_id,ordinal),UNIQUE(org_id,interview_id,subject_id),UNIQUE(org_id,interview_id,employee_id),CHECK((kind='subject' AND subject_id IS NOT NULL AND employee_id IS NULL) OR (kind='employee' AND employee_id IS NOT NULL AND subject_id IS NULL)),FOREIGN KEY(org_id,interview_id) REFERENCES interview(org_id,id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE interview_event(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,interview_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('scheduled','in_progress','completed','cancelled')),revision INTEGER NOT NULL CHECK(revision>0),actual_started_at INTEGER,actual_ended_at INTEGER,backfilled INTEGER NOT NULL CHECK(backfilled IN(0,1)),reason_payload_id TEXT,author_subject_id TEXT NOT NULL,recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,interview_id,revision),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,interview_id,employee_id),CHECK(backfilled=0 OR status='completed'),CHECK(actual_ended_at IS NULL OR (actual_started_at IS NOT NULL AND actual_ended_at>=actual_started_at)),CHECK(status<>'scheduled' OR (actual_started_at IS NULL AND actual_ended_at IS NULL)),CHECK(status<>'in_progress' OR (actual_started_at IS NOT NULL AND actual_ended_at IS NULL)),CHECK(status<>'completed' OR (actual_started_at IS NOT NULL AND actual_ended_at IS NOT NULL)),CHECK(actual_started_at IS NULL OR actual_started_at<=recorded_at),CHECK(actual_ended_at IS NULL OR actual_ended_at<=recorded_at),FOREIGN KEY(org_id,interview_id,employee_id) REFERENCES interview(org_id,id,employee_id),FOREIGN KEY(org_id,author_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,id,employee_id,reason_payload_id) REFERENCES interview_payload(org_id,interview_event_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE note_head(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,interview_id TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN('shared','manager_private','hr_confidential')),revision INTEGER NOT NULL CHECK(revision>0),acl_epoch INTEGER NOT NULL CHECK(acl_epoch>0),draft_version_id TEXT,published_version_id TEXT,draft_status TEXT NOT NULL DEFAULT 'draft' CHECK(draft_status='draft'),published_status TEXT NOT NULL DEFAULT 'published' CHECK(published_status='published'),PRIMARY KEY(org_id,id),UNIQUE(org_id,interview_id,category),UNIQUE(org_id,id,employee_id,category),UNIQUE(org_id,id,interview_id,employee_id,category),FOREIGN KEY(org_id,interview_id,employee_id) REFERENCES interview(org_id,id,employee_id),FOREIGN KEY(org_id,id,employee_id,category,draft_version_id,draft_status) REFERENCES note_version(org_id,head_id,employee_id,category,id,status) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,id,employee_id,category,published_version_id,published_status) REFERENCES note_version(org_id,head_id,employee_id,category,id,status) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE note_version(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,head_id TEXT NOT NULL,interview_id TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN('shared','manager_private','hr_confidential')),version_no INTEGER NOT NULL CHECK(version_no>0),status TEXT NOT NULL CHECK(status IN('draft','published')),payload_id TEXT NOT NULL,supersedes_version_id TEXT CHECK(supersedes_version_id IS NULL OR supersedes_version_id<>id),author_subject_id TEXT NOT NULL,recorded_at INTEGER NOT NULL,content_digest BLOB NOT NULL CHECK(length(content_digest)=32),source_epoch INTEGER NOT NULL CHECK(source_epoch>0),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id,category),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,head_id,version_no),UNIQUE(org_id,head_id,employee_id,category,id),UNIQUE(org_id,head_id,employee_id,category,id,status),UNIQUE(org_id,id,head_id,employee_id,category),UNIQUE(org_id,id,employee_id,category,version_no,source_epoch,status),FOREIGN KEY(org_id,head_id,interview_id,employee_id,category) REFERENCES note_head(org_id,id,interview_id,employee_id,category),FOREIGN KEY(org_id,head_id,employee_id,category,supersedes_version_id) REFERENCES note_version(org_id,head_id,employee_id,category,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(org_id,author_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,id,employee_id,payload_id) REFERENCES interview_payload(org_id,note_version_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE action_item(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,interview_id TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'shared' CHECK(category='shared'),owner_kind TEXT NOT NULL CHECK(owner_kind IN('subject','employee')),owner_subject_id TEXT,owner_employee_id TEXT,due_date TEXT CHECK(due_date IS NULL OR (length(due_date)=10 AND date(due_date,'+0 days') IS NOT NULL AND date(due_date,'+0 days')=due_date)),status TEXT NOT NULL CHECK(status IN('todo','in_progress','done','cancelled')),revision INTEGER NOT NULL CHECK(revision>0),payload_id TEXT NOT NULL,author_subject_id TEXT NOT NULL,recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,employee_id,category),UNIQUE(org_id,id,interview_id,employee_id),CHECK((owner_kind='subject' AND owner_subject_id IS NOT NULL AND owner_employee_id IS NULL) OR (owner_kind='employee' AND owner_employee_id IS NOT NULL AND owner_subject_id IS NULL)),FOREIGN KEY(org_id,interview_id,employee_id) REFERENCES interview(org_id,id,employee_id),FOREIGN KEY(org_id,owner_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,owner_employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,author_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,id,employee_id,payload_id) REFERENCES interview_payload(org_id,action_item_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE action_item_event(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,action_item_id TEXT NOT NULL,interview_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('todo','in_progress','done','cancelled')),revision INTEGER NOT NULL CHECK(revision>0),payload_id TEXT NOT NULL,author_subject_id TEXT NOT NULL,recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,action_item_id,revision),UNIQUE(org_id,id,employee_id),UNIQUE(org_id,id,action_item_id,employee_id),FOREIGN KEY(org_id,action_item_id,interview_id,employee_id) REFERENCES action_item(org_id,id,interview_id,employee_id),FOREIGN KEY(org_id,author_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,id,employee_id,payload_id) REFERENCES interview_payload(org_id,action_event_id,employee_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE interview_payload(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,record_id TEXT NOT NULL,version_id TEXT NOT NULL,object_kind TEXT NOT NULL CHECK(object_kind IN('interview_note_shared','interview_note_manager_private','interview_note_hr_confidential','interview_action','interview_reason')),purpose TEXT NOT NULL CHECK(purpose='interview'),schema_type TEXT NOT NULL CHECK(schema_type IN('interview.note.v1','interview.action.v1','interview.reason.v1')),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL CHECK(format_version=1),algorithm TEXT NOT NULL CHECK(algorithm='A256GCM-RANDOMNONCE'),dek_id TEXT NOT NULL,kek_id TEXT NOT NULL CHECK(length(kek_id)>0),kek_version INTEGER NOT NULL CHECK(kek_version>0),wrapped_dek BLOB NOT NULL CHECK(length(wrapped_dek)>0),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),created_at INTEGER NOT NULL,head_id TEXT,note_version_id TEXT,action_item_id TEXT,action_event_id TEXT,interview_id TEXT,interview_event_id TEXT,category TEXT CHECK(category IS NULL OR category IN('shared','manager_private','hr_confidential')),PRIMARY KEY(org_id,id),UNIQUE(org_id,note_version_id,employee_id,id),UNIQUE(org_id,action_item_id,employee_id,id),UNIQUE(org_id,action_event_id,employee_id,id),UNIQUE(org_id,interview_id,employee_id,id),UNIQUE(org_id,interview_event_id,employee_id,id),CHECK((object_kind IN('interview_note_shared','interview_note_manager_private','interview_note_hr_confidential') AND schema_type='interview.note.v1' AND head_id IS NOT NULL AND note_version_id IS NOT NULL AND record_id=head_id AND version_id=note_version_id AND action_item_id IS NULL AND action_event_id IS NULL AND interview_id IS NULL AND interview_event_id IS NULL) OR (object_kind='interview_action' AND schema_type='interview.action.v1' AND action_item_id IS NOT NULL AND action_event_id IS NOT NULL AND record_id=action_item_id AND version_id=id AND head_id IS NULL AND note_version_id IS NULL AND interview_i