CREATE TABLE source_reference(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,owner_note_version_id TEXT,owner_action_event_id TEXT,source_note_version_id TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN('shared','manager_private','hr_confidential')),expected_version INTEGER NOT NULL CHECK(expected_version>0),source_epoch INTEGER NOT NULL CHECK(source_epoch>0),source_status TEXT NOT NULL DEFAULT 'published' CHECK(source_status='published'),PRIMARY KEY(org_id,id),UNIQUE(org_id,owner_note_version_id,source_note_version_id),UNIQUE(org_id,owner_action_event_id,source_note_version_id),CHECK((owner_note_version_id IS NOT NULL AND owner_action_event_id IS NULL) OR (owner_note_version_id IS NULL AND owner_action_event_id IS NOT NULL)),FOREIGN KEY(org_id,owner_note_version_id,employee_id) REFERENCES note_version(org_id,id,employee_id),FOREIGN KEY(org_id,owner_action_event_id,employee_id) REFERENCES action_item_event(org_id,id,employee_id),FOREIGN KEY(org_id,source_note_version_id,employee_id,category,expected_version,source_epoch,source_status) REFERENCES note_version(org_id,id,employee_id,category,version_no,source_epoch,status)) STRICT;
CREATE TABLE interview_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-INT-02','OP-INT-03','OP-INT-05','OP-INT-07','OP-INT-08','OP-SEC-05')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),digest_key_version INTEGER NOT NULL CHECK(digest_key_version=1),result_json TEXT NOT NULL CHECK(json_valid(result_json) AND json_type(result_json)='object'),recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id)) STRICT;
