CREATE TABLE grant_command_receipt_v6(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-SEC-02','OP-SEC-03')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),digest_key_version INTEGER NOT NULL DEFAULT 1 CHECK(digest_key_version=1),result_id TEXT NOT NULL,result_revision INTEGER NOT NULL CHECK(result_revision>0),result_status TEXT NOT NULL CHECK(result_status IN('current','future','expired','revoked')),result_auth_epoch INTEGER NOT NULL CHECK(result_auth_epoch>0),PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,result_id) REFERENCES access_grant_v6(org_id,id)) STRICT;
