CREATE TABLE audit_event_v6(id TEXT PRIMARY KEY,org_id TEXT REFERENCES organization(id),subject_id TEXT,employee_id TEXT,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-01','OP-ORG-02','OP-ORG-03','OP-ORG-04','OP-ORG-05','OP-ORG-07','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND','OP-INT-01','OP-INT-02','OP-INT-03','OP-INT-04','OP-INT-05','OP-INT-06','OP-INT-07','OP-INT-08','OP-SEC-05')),purpose TEXT NOT NULL CHECK(purpose IN('organization_management','security_administration','interview_followup','')),request_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('allowed','denied','partial')),recorded_at INTEGER NOT NULL,grant_id TEXT,actor_kind TEXT NOT NULL DEFAULT 'application' CHECK(actor_kind IN('application','local_maintenance','legacy_unattributed')),actor_uid INTEGER,actor_host_hash BLOB CHECK(actor_host_hash IS NULL OR length(actor_host_hash)=32),target_subject_id TEXT,identity_digest BLOB CHECK(identity_digest IS NULL OR length(identity_digest)=32),target_employee_id TEXT,FOREIGN KEY(org_id,target_employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,target_subject_id,target_employee_id) REFERENCES subject_employee(org_id,subject_id,employee_id),CHECK(target_employee_id IS NULL OR (org_id IS NOT NULL AND target_subject_id IS NOT NULL)),CHECK(outcome<>'denied' OR target_employee_id IS NULL),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,grant_id) REFERENCES access_grant_v6(org_id,id),FOREIGN KEY(org_id,target_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(identity_digest,org_id,target_subject_id) REFERENCES subject_identity(digest,org_id,subject_id),CHECK(subject_id IS NULL OR org_id IS NOT NULL),CHECK(employee_id IS NULL OR org_id IS NOT NULL),CHECK(grant_id IS NULL OR org_id IS NOT NULL),CHECK(target_subject_id IS NULL OR org_id IS NOT NULL),CHECK(outcome<>'denied' OR employee_id IS NULL),CHECK(outcome<>'denied' OR grant_id IS NULL),CHECK((actor_kind='application' AND operation NOT IN('AUTH-BIND','AUTH-UNBIND') AND actor_uid IS NULL AND actor_host_hash IS NULL AND target_subject_id IS NULL AND target_employee_id IS NULL AND identity_digest IS NULL) OR (actor_kind='local_maintenance' AND operation IN('AUTH-BIND','AUTH-UNBIND') AND outcome='allowed' AND purpose='security_administration' AND org_id IS NOT NULL AND subject_id IS NULL AND employee_id IS NULL AND grant_id IS NULL AND actor_uid IS NOT NULL AND actor_uid BETWEEN 0 AND 4294967295 AND actor_host_hash IS NOT NULL AND target_subject_id IS NOT NULL AND identity_digest IS NOT NULL) OR (actor_kind='legacy_unattributed' AND target_employee_id IS NULL AND operation IN('AUTH-BIND','AUTH-UNBIND') AND actor_uid IS NULL AND actor_host_hash IS NULL AND identity_digest IS NULL AND ((target_subject_id IS NULL AND subject_id IS NULL) OR (target_subject_id IS NOT NULL AND subject_id IS NOT NULL AND target_subject_id=subject_id))))) STRICT;
