CREATE TRIGGER interview_owner_immutable BEFORE UPDATE ON interview WHEN NEW.org_id IS NOT OLD.org_id OR NEW.id IS NOT OLD.id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.scheduled_at IS NOT OLD.scheduled_at OR NEW.author_subject_id IS NOT OLD.author_subject_id OR NEW.recorded_at IS NOT OLD.recorded_at BEGIN SELECT RAISE(ABORT,'immutable interview owner'); END;
CREATE TRIGGER note_head_owner_immutable BEFORE UPDATE ON note_head WHEN NEW.org_id IS NOT OLD.org_id OR NEW.id IS NOT OLD.id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.interview_id IS NOT OLD.interview_id OR NEW.category IS NOT OLD.category BEGIN SELECT RAISE(ABORT,'immutable interview owner'); END;
CREATE TRIGGER action_item_owner_immutable BEFORE UPDATE ON action_item WHEN NEW.org_id IS NOT OLD.org_id OR NEW.id IS NOT OLD.id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.interview_id IS NOT OLD.interview_id OR NEW.category IS NOT OLD.category OR NEW.owner_kind IS NOT OLD.owner_kind OR NEW.owner_subject_id IS NOT OLD.owner_subject_id OR NEW.owner_employee_id IS NOT OLD.owner_employee_id OR NEW.due_date IS NOT OLD.due_date OR NEW.author_subject_id IS NOT OLD.author_subject_id OR NEW.recorded_at IS NOT OLD.recorded_at BEGIN SELECT RAISE(ABORT,'immutable interview owner'); END;
CREATE TRIGGER access_grant_owner_immutable BEFORE UPDATE ON access_grant WHEN NEW.id IS NOT OLD.id OR NEW.org_id IS NOT OLD.org_id OR NEW.subject_id IS NOT OLD.subject_id OR NEW.capability IS NOT OLD.capability OR NEW.category IS NOT OLD.category OR NEW.scope_kind IS NOT OLD.scope_kind OR NEW.scope_id IS NOT OLD.scope_id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.purpose IS NOT OLD.purpose OR NEW.object_ref IS NOT OLD.object_ref OR NEW.object_kind IS NOT OLD.object_kind OR NEW.object_employee_id IS NOT OLD.object_employee_id OR NEW.interview_id IS NOT OLD.interview_id OR NEW.note_head_id IS NOT OLD.note_head_id OR NEW.note_version_id IS NOT OLD.note_version_id OR NEW.action_item_id IS NOT OLD.action_item_id BEGIN SELECT RAISE(ABORT,'immutable interview owner'); END;
CREATE TRIGGER approval_target BEFORE INSERT ON access_grant_source_approval WHEN NOT EXISTS(SELECT 1 FROM access_grant g JOIN note_version v ON v.org_id=g.org_id AND v.id=NEW.source_note_version_id WHERE g.org_id=NEW.org_id AND g.id=NEW.grant_id AND v.employee_id=NEW.employee_id AND v.category=NEW.source_category AND v.status='published' AND ((g.capability='note.publish' AND g.category IN('shared','manager_private','hr_confidential')) OR (g.capability='action.write' AND g.category='shared')) AND g.purpose='interview_followup' AND g.scope_kind='employee' AND g.employee_id=NEW.employee_id AND (g.object_kind IS NULL OR g.object_employee_id=NEW.employee_id)) OR (SELECT count(*) FROM access_grant_source_approval WHERE org_id=NEW.org_id AND grant_id=NEW.grant_id)>=10 BEGIN SELECT RAISE(ABORT,'invalid source approval'); END;
CREATE TRIGGER source_reference_limit BEFORE INSERT ON source_reference WHEN (NEW.owner_note_version_id IS NOT NULL AND (SELECT count(*) FROM source_reference WHERE org_id=NEW.org_id AND owner_note_version_id=NEW.owner_note_version_id)>=10) OR (NEW.owner_action_event_id IS NOT NULL AND (SELECT count(*) FROM source_reference WHERE org_id=NEW.org_id AND owner_action_event_id=NEW.owner_action_event_id)>=10) BEGIN SELECT RAISE(ABORT,'too many sources'); END;
CREATE TRIGGER interview_transition_guard BEFORE UPDATE ON interview WHEN NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='scheduled' AND (NEW.status IN('scheduled','in_progress','cancelled') OR (NEW.status='completed' AND NEW.backfilled=1))) OR (OLD.status='in_progress' AND NEW.status IN('in_progress','completed','cancelled'))) OR (NEW.backfilled IS NOT OLD.backfilled AND NOT (OLD.backfilled=0 AND NEW.backfilled=1 AND OLD.status='scheduled' AND NEW.status='completed')) OR (OLD.actual_started_at IS NOT NULL AND NEW.actual_started_at IS NOT OLD.actual_started_at) OR (OLD.actual_ended_at IS NOT NULL AND NEW.actual_ended_at IS NOT OLD.actual_ended_at) BEGIN SELECT RAISE(ABORT,'invalid interview transition'); END;
CREATE TRIGGER action_transition_guard BEFORE UPDATE ON action_item WHEN NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='todo' AND NEW.status IN('in_progress','done','cancelled')) OR (OLD.status='in_progress' AND NEW.status IN('done','cancelled'))) BEGIN SELECT RAISE(ABORT,'invalid action transition'); END;
CREATE UNIQUE INDEX interview_event_phase ON interview_event(org_id,interview_id,CASE WHEN status IN('completed','cancelled') THEN 'terminal' ELSE status END);
CREATE TABLE oidc_transaction_v6(state_hash BLOB PRIMARY KEY CHECK(length(state_hash)=32),binding_hash BLOB NOT NULL CHECK(length(binding_hash)=32),sealed_bytes BLOB NOT NULL CHECK(length(sealed_bytes)>=28),key_version INTEGER NOT NULL CHECK(key_version=1),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>created_at AND expires_at<=created_at+600000000),mode TEXT NOT NULL CHECK(mode IN('login','step_up')),action TEXT NOT NULL CHECK(action IN('','pii.write','access_grant.manage','note.publish','sensitive.export')),return_route TEXT NOT NULL CHECK(length(return_route)<=128),previous_hash BLOB,expected_org TEXT,expected_subject TEXT,expected_epoch INTEGER,expected_identity BLOB,consumed INTEGER NOT NULL DEFAULT 0 CHECK(consumed IN(0,1)),issued_hash BLOB REFERENCES session(token_hash),FOREIGN KEY(previous_hash,expected_org,expected_subject) REFERENCES session(token_hash,org_id,subject_id),FOREIGN KEY(expected_org,expected_subject) REFERENCES subject(org_id,id),FOREIGN KEY(expected_identity,expected_org,expected_subject) REFERENCES subject_identity(digest,org_id,subject_id),CHECK((previous_hash IS NULL AND expected_org IS NULL AND expected_subject IS NULL AND expected_epoch IS NULL) OR (previous_hash IS NOT NULL AND expected_org IS NOT NULL AND expected_subject IS NOT NULL AND expected_epoch IS NOT NULL AND expected_epoch>0)),CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','note.publish','sensitive.export') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL)),CHECK(consumed=1 OR issued_hash IS NULL)) STRICT;
INSERT INTO oidc_transaction_v6 SELECT * FROM oidc_transaction;
DROP TABLE oidc_transaction;
ALTER TABLE oidc_transaction_v6 RENAME TO oidc_transaction;
CREATE INDEX oidc_transaction_expiry ON oidc_transaction(expires_at);
